rify specific rental dates, full-court access, insurance, staffing and ticket sales; no live booking inventory verified.","availability_checked_on":null,"phone":null,"email":null,"website":"https://www.loudoun.gov/6243/ARCC-Facility-Rentals-Party-Packages","region_group":"Northern Virginia","venue_kind":"recreation_center","rental_allowed":null,"court_count":null,"source_verification":"official","notes":""}]$rcl_gymseed$::jsonb)
 as v(source_key text,name text,city text,address text,source_url text,source_label text,source_checked_on date,rate_basis text,hourly_rate numeric,effective_hourly_rate numeric,rate_details text,budget_status text,availability_status text,availability_details text,availability_checked_on date,phone text,email text,website text,region_group text,venue_kind text,rental_allowed boolean,court_count integer,source_verification text,notes text)
)
insert into public.rcl_command_venues
 (source_key,name,city,address,source_url,source_label,source_checked_on,rate_basis,hourly_rate,effective_hourly_rate,rate_details,budget_status,availability_status,availability_details,availability_checked_on,phone,email,website,region_group,venue_kind,rental_allowed,court_count,source_verification,notes,created_by)
select s.source_key,s.name,s.city,s.address,s.source_url,s.source_label,s.source_checked_on,s.rate_basis,s.hourly_rate,s.effective_hourly_rate,s.rate_details,s.budget_status,s.availability_status,s.availability_details,s.availability_checked_on,s.phone,s.email,s.website,s.region_group,s.venue_kind,s.rental_allowed,s.court_count,s.source_verification,s.notes,a.id
from imported s cross join admin_actor a
where not exists (select 1 from public.rcl_command_venues v
 where lower(v.name)=lower(s.name) and lower(v.city)=lower(s.city))
on conflict do nothing;

-- Supplement the official and community RCH directory's indoor/mixed venues as
-- LEADS. Do not copy open gym hours into availability or copy membership fees.
with admin_actor as (
 select id from public.profiles where role::text='admin' and coalesce(is_active,true) order by id limit 1
)
insert into public.rcl_command_venues
(source_key,name,city,address,source_url,source_label,source_checked_on,
 availability_status,availability_details,budget_status,rate_details,
 website,region_group,venue_kind,source_verification,
 rental_allowed,origin_location_slug,latitude,longitude,court_count,notes,created_by)
select 'rcl-location:'||l.slug,l.name,l.locality,
 case when l.address ilike 'Street address not provided%' then '' else coalesce(l.address,'') end,
 l.source_url,l.source_label,l.last_verified_on,
 'unverified','Basketball location reported in the RCH court directory. Gym availability, rental eligibility, staffing and dated reservations are NOT verified.',
 'needs_quote','No verified exclusive full-gym hourly rental fee.',
 l.source_url,
 case
 when l.locality ~* 'Richmond|Henrico|Chester|Midlothian' then 'Richmond Metro'
 when l.locality ~* 'Norfolk|Hampton|Chesapeake|Virginia Beach|York' then 'Hampton Roads'
 when l.locality ~* 'Fairfax|Arlington|Alexandria|Prince William|Loudoun' then 'Northern Virginia'
 when l.locality ~* 'Shenandoah|Rockingham' then 'Shenandoah Valley'
 when l.locality ~* 'Lynchburg|Campbell' then 'Southside & Southwest'
 else 'Central Virginia' end,
 case when l.venue_type='mixed' then 'mixed' else 'indoor_gym' end,
 case when l.verification_status in ('official','provider','community') then l.verification_status else 'community' end,
 null,l.slug,l.latitude,l.longitude,l.court_count,
 concat('Existing RCH court listing (',coalesce(l.verification_status,'unverified'),'). ',coalesce(l.notes,'')),a.id
from public.basketball_locations l cross join admin_actor a
where l.is_active is distinct from false
  and l.venue_type in ('indoor','mixed')
  and l.name not ilike 'Basketball Court · %'
  and l.name not in ('Main Gym','Gymnasium','Madison Manor Basketball Court')
  and not exists (
   select 1 from public.rcl_command_venues v
   where lower(v.name)=lower(l.name)
     and (lower(v.city)=lower(l.locality)
          or (v.address <> '' and v.address=l.address))
  )
on conflict do nothing;
